734	func (s *service) applySubscriptionRoutingCost(entry *routing.HarnessEntry, cat *modelcatalog.Catalog) {
735		if entry == nil || !entry.IsSubscription {
736			return
737		}
738		baseCost, ok := catalogCostUSDPer1kTokens(cat, entry.DefaultModel)
739		if !ok {
740			baseCost, ok = catalogCostUSDPer1kTokens(cat, subscriptionFallbackProfile(entry.Name))
741			if !ok {
742				baseCost = 0
743			}
744		}
745		cost := subscriptionEffectiveCostUSDPer1kTokens(baseCost, entry.QuotaPercentUsed, s.subscriptionCostCurve())
746		entry.Providers = []routing.ProviderEntry{{
747			CostUSDPer1kTokens: cost,
748			CostSource:         routing.CostSourceSubscription,
749		}}
750	}
