770	func catalogCostUSDPer1kTokens(cat *modelcatalog.Catalog, modelID string) (float64, bool) {
771		if cat == nil || strings.TrimSpace(modelID) == "" {
772			return 0, false
773		}
774		entry, ok := cat.LookupModel(modelID)
775		if !ok {
776			resolved := resolveCatalogCostModel(cat, modelID)
777			if resolved == "" {
778				return 0, false
779			}
780			entry, ok = cat.LookupModel(resolved)
781			if !ok {
782				return 0, false
783			}
784		}
785		input := entry.CostInputPerM
786		if input == 0 {
787			input = entry.CostInputPerMTok
788		}
789		output := entry.CostOutputPerM
790		if output == 0 {
791			output = entry.CostOutputPerMTok
792		}
793		switch {
794		case input > 0 && output > 0:
795			return ((input + output) / 2) / 1000, true
796		case input > 0:
797			return input / 1000, true
798		case output > 0:
799			return output / 1000, true
800		default:
801			return 0, false
802		}
803	}
