875	// probeEndpointDiscoveredIDs returns the foreground /v1/models catalog for one
876	// endpoint. Dispatch routing must not use stale cache hits: a recently dead
877	// endpoint has to be skipped before any chat request is attempted.
878	func (s *service) probeEndpointDiscoveredIDs(ctx context.Context, pcfg ServiceProviderEntry, baseURL string) ([]string, bool) {
879		if baseURL == "" {
880			return nil, false
881		}
882		probeCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
883		defer cancel()
884		ids, err := probeOpenAIModels(probeCtx, baseURL, pcfg.APIKey)
885		if err != nil || len(ids) == 0 {
886			return nil, false
887		}
888		return ids, true
