891	// resolveExecuteRouteWithEngine is the post-engine variant of resolveExecuteRoute.
892	// It is invoked by Execute when the request is under-specified
893	// (no PreResolved, no fully-specified Harness). Returns nil when the request
894	// is already specific enough that the legacy resolveExecuteRoute path applies.
895	func (s *service) resolveExecuteRouteWithEngine(req ServiceExecuteRequest) (*RouteDecision, error) {
896		rr := RouteRequest{
897			Profile:     req.Profile,
898			Model:       req.Model,
899			Provider:    req.Provider,
900			Harness:     req.Harness,
901			ModelRef:    req.ModelRef,
902			Reasoning:   req.Reasoning,
903			Permissions: req.Permissions,
904			CachePolicy: req.CachePolicy,
905			MinPower:    req.MinPower,
906			MaxPower:    req.MaxPower,
907		}
908		dec, err := s.ResolveRoute(context.Background(), rr)
909		if err != nil {
910			if isExplicitPinError(err) {
911				return nil, err
912			}
913			return nil, fmt.Errorf("ResolveRoute: %w", err)
914		}
915		return dec, nil
916	}
