918	func providerPreferenceForProfile(cat *modelcatalog.Catalog, profile string) (string, error) {
919		if profile == "" {
920			return routing.ProviderPreferenceLocalFirst, nil
921		}
922		if cat == nil {
923			return "", &ErrUnknownProfile{Profile: profile}
924		}
925		info, ok := cat.Profile(profile)
926		if !ok {
927			return "", &ErrUnknownProfile{Profile: profile}
928		}
929		switch info.ProviderPreference {
930		case routing.ProviderPreferenceLocalOnly, routing.ProviderPreferenceSubscriptionOnly,
931			routing.ProviderPreferenceLocalFirst, routing.ProviderPreferenceSubscriptionFirst:
932			return info.ProviderPreference, nil
933		default:
934			return "", fmt.Errorf("profile %q has unsupported provider preference %q", profile, info.ProviderPreference)
935		}
936	}
