package fizeau

import (
	"sort"
	"sync"
	"time"
)

// ProviderQuotaState enumerates the per-provider quota state for routing.
//
// The state machine is deliberately minimal: a provider is either available
// (the routing engine considers it for selection) or quota_exhausted (the
// routing engine excludes it until RetryAfter passes). Sibling beads add the
// header-parsing, burn-rate, and probe-based transition triggers; this bead
// only owns the storage and transition API.
type ProviderQuotaState string

const (
	// ProviderQuotaAvailable means the provider is selectable by routing.
	// This is the implicit default for providers with no recorded state.
	ProviderQuotaAvailable ProviderQuotaState = "available"
	// ProviderQuotaExhausted means the provider has reported a quota
	// limit and should be excluded from routing until RetryAfter.
	ProviderQuotaExhausted ProviderQuotaState = "quota_exhausted"
)

// ProviderQuotaSnapshot is one provider's quota state at a point in time.
type ProviderQuotaSnapshot struct {
	Provider   string
	State      ProviderQuotaState
	RetryAfter time.Time
}

type providerQuotaStore struct {
	mu     sync.RWMutex
	states map[string]ProviderQuotaSnapshot
}

func newProviderQuotaStore() *providerQuotaStore {
	return &providerQuotaStore{states: make(map[string]ProviderQuotaSnapshot)}
}

// markExhausted transitions the provider into the quota_exhausted state with
// the supplied retry_after timestamp. retryAfter is the earliest moment at
// which the provider is expected to recover; the routing engine excludes the
// provider until clock time passes that point. Calls with a non-future
// retryAfter are normalized to "now"; the next routing pass will then clear
// the entry.
func (s *providerQuotaStore) markExhausted(provider string, retryAfter time.Time) {
	if provider == "" {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.states[provider] = ProviderQuotaSnapshot{
		Provider:   provider,
		State:      ProviderQuotaExhausted,
		RetryAfter: retryAfter,
	}
}

// markAvailable transitions the provider back to the available state by
// removing its quota_exhausted record. Idempotent.
func (s *providerQuotaStore) markAvailable(provider string) {
	if provider == "" {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.states, provider)
}

// snapshot returns the current state for one provider. Providers with no
// recorded state report ProviderQuotaAvailable.
func (s *providerQuotaStore) snapshot(provider string) ProviderQuotaSnapshot {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if rec, ok := s.states[provider]; ok {
		return rec
	}
	return ProviderQuotaSnapshot{Provider: provider, State: ProviderQuotaAvailable}
}

// exhaustedAt returns the map of provider names to their RetryAfter timestamps
// for providers whose state is quota_exhausted with retry_after strictly after
// `now`. Providers whose retry_after is at or before `now` are auto-cleared.
//
// Returned map is a fresh copy safe for the caller to mutate.
func (s *providerQuotaStore) exhaustedAt(now time.Time) map[string]time.Time {
	s.mu.Lock()
	defer s.mu.Unlock()
	if len(s.states) == 0 {
		return nil
	}
	out := make(map[string]time.Time, len(s.states))
	for name, rec := range s.states {
		if rec.State != ProviderQuotaExhausted {
			continue
		}
		if !rec.RetryAfter.After(now) {
			delete(s.states, name)
			continue
		}
		out[name] = rec.RetryAfter
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// MarkProviderQuotaExhausted records that `provider` has hit its quota and
// will not recover until `retryAfter`. The routing engine excludes the
// provider from candidate selection until clock time passes retryAfter. The
// transition is explicit so sibling beads (header parsing, burn-rate, probe
// behavior) can trigger it from their own observation paths.
func (s *service) MarkProviderQuotaExhausted(provider string, retryAfter time.Time) {
	if s.providerQuota == nil {
		return
	}
	s.providerQuota.markExhausted(provider, retryAfter)
}

// MarkProviderQuotaAvailable returns `provider` to the available state,
// allowing the routing engine to consider it for selection again.
func (s *service) MarkProviderQuotaAvailable(provider string) {
	if s.providerQuota == nil {
		return
	}
	s.providerQuota.markAvailable(provider)
}

// ProviderQuotaSnapshot returns the current quota state for `provider`. A
// provider with no recorded state reports ProviderQuotaAvailable.
func (s *service) ProviderQuotaSnapshot(provider string) ProviderQuotaSnapshot {
	if s.providerQuota == nil {
		return ProviderQuotaSnapshot{Provider: provider, State: ProviderQuotaAvailable}
	}
	return s.providerQuota.snapshot(provider)
}

// providerQuotaExhaustedAt returns the live exhaustion map for routing
// inputs at the supplied time. Auto-clears entries whose RetryAfter has
// already passed.
func (s *service) providerQuotaExhaustedAt(now time.Time) map[string]time.Time {
	if s.providerQuota == nil {
		return nil
	}
	return s.providerQuota.exhaustedAt(now)
}

// sortedExhaustedProviders returns the names from `m` in stable order.
// Deterministic ordering keeps NoViableProviderForNow.ExhaustedProviders
// stable for callers that diff or log it.
func sortedExhaustedProviders(m map[string]time.Time) []string {
	if len(m) == 0 {
		return nil
	}
	out := make([]string, 0, len(m))
	for name := range m {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

